    .param .u64 output_ptr,
    .param .u32 dim
)
{
    // ------------------------------
    // Thread and block indices
    // ------------------------------
    .reg .pred   %p;
    .reg .u32    %tid, %bid, %bdim, %dim;
    .reg .u64    %in_ptr, %out_ptr;
    .reg .u64    %row_offset;
    .reg .u32    %idx;

    mov.u32      %tid, %tid.x;
    mov.u32      %bid, %ctaid.x;
    mov.u32      %bdim, %ntid.x;

    ld.param.u64 %in_ptr, [input_ptr];
    ld.param.u64 %out_ptr, [output_ptr];
    ld.param.u32 %dim, [dim];

    // Compute row offset = bid * dim
    mul.wide.u32 %row_offset, %bid, %dim;
    cvt.u64.u32 %row_offset, %row_offset;

    // Adjust base pointers to the start of this row
    add.u64 %in_ptr, %in_ptr, %row_offset;
    add.u64 %out_ptr, %out_ptr, %row_offset;

    // ------------------------------
    // Shared memory for reductions
    // ------------------------------
    .shared .align 4 .b8 shmem_max[256*4];
    .shared .align 4 .b8 shmem_sum[256*4];

    // ------------------------------
    // Phase 1: Compute per‑row maximum
    // ------------------------------
    .reg .f32   %local_max, %temp_f32;
    .reg .f16   %val_f16;

    // Initialize to very low value
    mov.f32 %local_max, -1e20;

    mov.u32 %idx, %tid;
L_max_loop:
    setp.ge.u32 %p, %idx, %dim;
    @%p bra L_max_done;

    // Load fp16
    mul.wide.u32 %temp_f32, %idx, 2;         // element offset in bytes
    add.u64 %temp_f32, %in_ptr, %temp_f32;
    ld.global.nc.f16 %val_f16, [%temp_f32];
    // Convert to fp32
    cvt.f32.f16 %temp_f32, %val_f16;
    // Max reduction
    max.f32 %local_max, %local_max, %temp_f32;

    add.u32 %idx, %idx, %bdim;
    bra L_max_loop;
L_max_done:

    // Store local max to shared memory
    mul.wide.u32 %temp_f32, %tid, 4;
    add.u64 %temp_f32, %shmem_max, %temp_f32;
    st.shared.f32 [%temp_f32], %local_max;
    bar.sync 0;

