    mov.u32 %stride, 128;
L_reduce_max:
    setp.lt.u32 %p, %tid, %stride;
    @%p {
        mul.wide.u32 %temp_f32, %tid, 4;
        add.u64 %temp_f32, %shmem_max, %temp_f32;
        ld.shared.f32 %temp_f32, [%temp_f32];
        mul.wide.u32 %temp_f32, %tid, 4;
        add.u64 %temp_f32, %shmem_max, %temp_f32;
        ld.shared.f32 %temp_f32, [%temp_f32];
        max.f32 %temp_f32, %temp_f32, %temp_f32;
        mul.wide.u32 %temp_f32, %tid, 4;
        add.u64 %temp_f32, %shmem_max, %temp_f32;
        st.shared.f32 [%temp_f32], %temp_f32;
