    // ------------------------------
    .reg .f32 %local_sum, %diff, %exp_val, %tmp;
    mov.f32 %local_sum, 0.0;

    mov.u32 %idx, %tid;
L_sum_loop:
    setp.ge.u32 %p, %idx, %dim;
    @%p bra L_sum_done;

