    mul.wide.u32 %temp_f32, %idx, 2;
    add.u64 %temp_f32, %in_ptr, %temp_f32;
    ld.global.nc.f16 %val_f16, [%temp_f32];
    // Convert to fp32
    cvt.f32.f16 %temp_f32, %val_f16;
    // diff = val - max
    sub.f32 %diff, %temp_f32, %local_max;
    // exp approximation: exp(x) ≈ 2^(x * log2(e))
    mul.f32 %tmp, %diff, 1.4426950408889634;   // log2(e)
    ex2.approx.f32 %exp_val, %tmp;
    // Accumulate
    add.f32 %local_sum, %local_sum, %exp_val;

    add.u32 %idx, %idx, %bdim;
    bra L_sum_loop;
L_sum_done:

