    mul.wide.u32 %temp_f32, %tid, 4;
    add.u64 %temp_f32, %shmem_sum, %temp_f32;
    st.shared.f32 [%temp_f32], %local_sum;
    bar.sync 0;

    // Reduce sum in shared memory (binary tree)
    mov.u32 %stride, 128;
L_reduce_sum:
    setp.lt.u32 %p, %tid, %stride;
    @%p {
        mul.wide.u32 %temp_f32, %tid, 4;
        add.u64 %temp_f32, %shmem_sum, %temp_f32;
        ld.shared.f32 %temp_f32, [%temp_f32];
        mul.wide.u32 %tmp, %tid, 4;
        add.u64 %tmp, %shmem_sum, %tmp;
        add.u64 %tmp, %tmp, %stride*4;
        ld.shared.f32 %tmp, [%tmp];
