    ld.shared.f32 %local_sum, [%shmem_sum];
    // Compute inverse sum
    rcp.approx.f32 %local_sum, %local_sum;   // now %local_sum holds 1/sum

    // ------------------------------
    // Phase 3: Write softmax results
    // ------------------------------
    mov.u32 %idx, %tid;
L_write_loop:
    setp.ge.u32 %p, %idx, %dim;
    @%p bra L_write_done;

    // Load fp16
    mul.wide.u32 %temp_f32, %idx, 2;
    add.u64 %temp_f32, %in_ptr, %temp_f32;
    ld.global.nc.f16 %val_f16, [%temp_f32];
    // Convert to fp32
    cvt.f32.f16 %temp_f32, %val_f16;
    // diff = val - max
    sub.f32 %diff, %temp_f32, %local_max;
    // exp approximation
    mul.f32 %tmp, %diff, 1.4426950408889634;
    ex2.approx.f32 %exp_val, %tmp;
    // softmax = exp * inv_sum
    mul.f32 %exp_val, %exp_val, %local_sum;
    // Convert back to fp16 (round to nearest even)
    cvt.rn.f16.f32 %val_f16, %exp_val;
    // Store output
    mul.wide.u32 %temp_f32, %idx, 2;
    add.u64 %temp_f32, %out_ptr, %temp_f32;
    st.global.f16 [%temp_f32], %val_f16;

    add.u32 %idx, %idx, %bdim;
    bra L_write_loop;
L_write_done:

    ret;
}
"""

