# Python wrapper class that loads and launches the PTX kernel
# ----------------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch   # Provided by the testing harness

class ModelNew:
    def __init__(self):
        # Load PTX module once
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, inputs):
